mapper.select:
SELECT pm.id, pm.product_id, pm.management_status, pm.priority, pm.assignee, pm.expected_completion_time, pm.actual_completion_time, pm.management_notes, pm.create_time, pm.update_time, p.name as product_name, p.product_sn, b.name as brand_name, pc.name as category_name FROM product_management pm LEFT JOIN pms_product p ON pm.product_id = p.id LEFT JOIN pms_brand b ON p.brand_id = b.id LEFT JOIN pms_product_category pc ON p.product_category_id = pc.id
AND pm.product_id = #{param.productId}
AND pm.management_status = #{param.managementStatus}
AND pm.priority = #{param.priority}
AND pm.assignee = #{param.assignee}
AND pm.create_time >= #{param.startTime}
AND pm.create_time <= #{param.endTime}
AND (p.name LIKE CONCAT('%', #{param.keyword}, '%') OR p.product_sn LIKE CONCAT('%', #{param.keyword}, '%') OR pm.management_notes LIKE CONCAT('%', #{param.keyword}, '%'))
ORDER BY pm.priority DESC, pm.create_time DESC
